#!/usr/bin/env node
import fs from 'node:fs';

const TYPES = ['feat', 'fix', 'docs', 'style', 'refactor', 'perf', 'test', 'build', 'ci', 'chore', 'revert'];
const HEADER = new RegExp(`^(${TYPES.join('|')})(\\([a-z0-9][a-z0-9._/-]*\\))?(!)?: .+`);
const MAX_HEADER = 72;

// Merge commits and autosquash markers are generated by git itself; a squash
// rebase resolves them before they can reach the mainline.
const EXEMPT = /^(Merge |Revert "|fixup!|squash!|amend!)/;

const messagePath = process.argv[2];
if (!messagePath) {
  console.error('check-commit-msg: missing commit message file argument');
  process.exit(1);
}

const header = fs.readFileSync(messagePath, 'utf8')
  .split(/\r?\n/)
  .find(line => line.trim() !== '' && !line.startsWith('#')) ?? '';

if (EXEMPT.test(header)) process.exit(0);

const errors = [];
if (!HEADER.test(header)) {
  errors.push('header must be "<type>(<scope>)!: <subject>"');
}
if (header.length > MAX_HEADER) {
  errors.push(`header is ${header.length} chars, limit is ${MAX_HEADER}`);
}
if (/\.$/.test(header)) {
  errors.push('header must not end with a period');
}

if (errors.length === 0) process.exit(0);

console.error('check-commit-msg: rejected\n');
console.error(`  ${header || '(empty)'}\n`);
for (const error of errors) console.error(`  - ${error}`);
console.error(`
Allowed types: ${TYPES.join(', ')}
Example: feat(session-call): reject ambiguous target prefixes`);
process.exit(1);
